	| EventEnvelope<"transcript.delta", {
		transcriptId: string;
		messageId?: string;
		role: "user" | "assistant";
		delta: string;
		final: boolean;
	}>
	| EventEnvelope<"message.completed", { messageId: string }>
	| EventEnvelope<"tool.requested", {
		callId: string;
		name: string;
		arguments: Record<string, JsonValue>;
	}>
	| EventEnvelope<"tool.started", { callId: string }>
	| EventEnvelope<"tool.progress", { callId: string; update: JsonValue }>
	| EventEnvelope<"tool.completed", { callId: string; result: JsonValue }>
	| EventEnvelope<"tool.failed", { callId: string; error: ProtocolError }>
	| EventEnvelope<"tool.cancelled", { callId: string; reason?: string }>
	| EventEnvelope<"ui.document.upserted", { document: UIDocument }>
	| EventEnvelope<"ui.action", { action: UIAction }>
	| EventEnvelope<"conversation.interrupted", {
		by: "user" | "host" | "provider";
		reason?: string;
		atMessageId?: string;
		atAudioStreamId?: string;
	}>
	| EventEnvelope<"reconnect.started", { attempt: number; reason?: string }>
	| EventEnvelope<"reconnect.succeeded", { attempt: number; resumedFromSequence?: number }>
	| EventEnvelope<"reconnect.failed", { attempt: number; error: ProtocolError; retryable: boolean }>
	| EventEnvelope<"error", { error: ProtocolError; fatal: boolean }>
	| EventEnvelope<"run.completed", { reason: "completed" | "cancelled" | "interrupted" | "error" }>;

export interface ProtocolError {
	code: string;
	message: string;
	provider?: string;
	details?: JsonValue;
}

export type EventOfType<T extends ConversationEvent["type"]> = Extract<ConversationEvent, { type: T }>;

export interface EventMetadata {
	id: string;
	sequence: number;
	timestamp: string;
	sessionId: string;
	runId: string;
}

export function conversationEvent<T extends ConversationEvent["type"]>(
	type: T,
	payload: EventOfType<T>["payload"],
	metadata: EventMetadata,
): EventOfType<T> {
	return {
		version: CONVERSATION_PROTOCOL_VERSION,
		type,
		payload,
		...metadata,
	} as EventOfType<T>;
}

function record(value: unknown): value is Record<string, unknown> {
	return value !== null && typeof value === "object" && !Array.isArray(value);
}

function nonEmptyString(value: unknown): value is string {
	return typeof value === "string" && value.trim().length > 0;
}

function safeSequence(value: unknown): value is number {
	return Number.isSafeInteger(value) && (value as number) >= 0;
}

function jsonValue(value: unknown, seen = new Set<object>()): value is JsonValue {
	if (value === null || typeof value === "string" || typeof value === "boolean") return true;
	if (typeof value === "number") return Number.isFinite(value);
	if (typeof value !== "object" || seen.has(value as object)) return false;
	seen.add(value as object);
	const valid = Array.isArray(value)
		? value.every((entry) => jsonValue(entry, seen))
		: Object.entries(value as Record<string, unknown>).every(([key, entry]) => key !== "__proto__" && jsonValue(entry, seen));
	seen.delete(value as object);
	return valid;
}

function protocolError(value: unknown): boolean {
	return record(value) && nonEmptyString(value.code) && nonEmptyString(value.message)
		&& (value.provider === undefined || typeof value.provider === "string")
		&& (value.details === undefined || jsonValue(value.details));
}

function uiDocument(value: unknown): value is UIDocument {
	return record(value) && nonEmptyString(value.id) && nonEmptyString(value.kind)
		&& ["ephemeral", "resumable", "workspace"].includes(String(value.lifecycle))
		&& safeSequence(value.revision) && jsonValue(value.content)
		&& (value.state === undefined || (record(value.state) && jsonValue(value.state)));
}

export function isUIAction(value: unknown): value is UIAction {
	return record(value) && nonEmptyString(value.id) && nonEmptyString(value.documentId)
		&& safeSequence(value.documentRevision) && nonEmptyString(value.type)
		&& record(value.params) && jsonValue(value.params)
		&& (value.formState === undefined || (record(value.formState) && jsonValue(value.formState)))
		&& (value.humanFriendlyMessage === undefined || typeof value.humanFriendlyMessage === "string");
}

