export function isConversationEvent(value: unknown): value is ConversationEvent {
	if (!record(value) || value.version !== CONVERSATION_PROTOCOL_VERSION || !nonEmptyString(value.id)
		|| !safeSequence(value.sequence) || !nonEmptyString(value.timestamp) || Number.isNaN(Date.parse(value.timestamp))
		|| !nonEmptyString(value.sessionId) || !nonEmptyString(value.runId) || !nonEmptyString(value.type)
		|| !record(value.payload)) return false;
