		case "run.started": return ["text", "voice", "multimodal"].includes(String(p.mode));
		case "text.delta": return nonEmptyString(p.messageId) && ["user", "assistant", "system", "tool"].includes(String(p.role)) && typeof p.delta === "string";
		case "audio.delta": return nonEmptyString(p.streamId) && ["user", "assistant"].includes(String(p.role)) && nonEmptyString(p.encoding) && typeof p.data === "string";
		case "transcript.delta": return nonEmptyString(p.transcriptId) && ["user", "assistant"].includes(String(p.role)) && typeof p.delta === "string" && typeof p.final === "boolean";
		case "message.completed": return nonEmptyString(p.messageId);
		case "tool.requested": return nonEmptyString(p.callId) && nonEmptyString(p.name) && record(p.arguments) && jsonValue(p.arguments);
		case "tool.started": return nonEmptyString(p.callId);
		case "tool.progress": return nonEmptyString(p.callId) && jsonValue(p.update);
		case "tool.completed": return nonEmptyString(p.callId) && jsonValue(p.result);
		case "tool.failed": return nonEmptyString(p.callId) && protocolError(p.error);
		case "tool.cancelled": return nonEmptyString(p.callId) && (p.reason === undefined || typeof p.reason === "string");
		case "ui.document.upserted": return uiDocument(p.document);
