export function isJsonValue(value: unknown, seen = new WeakSet<object>()): value is JsonValue {
	if (value === null || string(value) || typeof value === "boolean" || (typeof value === "number" && Number.isFinite(value))) return true;
	if (typeof value !== "object") return false;
	if (seen.has(value)) return false;
	seen.add(value);
	if (Array.isArray(value)) return value.every((item) => isJsonValue(item, seen));
	return Object.values(value as Record<string, unknown>).every((item) => isJsonValue(item, seen));
